"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { cn } from "@/lib/utils";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { BorderBeam } from "@/components/magicui/border-beam";
//font
import {DM_Sans} from "next/font/google";

const DMsansFont = DM_Sans({
  subsets: ["latin"],
})

const navItems = [
  { name: "Home", href: "/" },
  { name: "Docs", href: "/docs" },
  { name: "Showcase", href: "/showcase" },
];



export function LandingNavbar() {
  const pathname = usePathname();

  return (
      <div className="navbar bg-transparent sticky top-0 z-50 w-full">
        <div className="navbar-start">
            <Link href="/" className="text-xl font-semibold tracking-tight">
               <h3 className="text-xl">MitraAI</h3>
            </Link> 
        </div>
        <div className={` ${DMsansFont.className} navbar-center text-5xl`}>
            <Card className="relative rounded-full bg-white/70 dark:bg-black/40 shadow-md border border-neutral-300 dark:border-neutral-700 px-6 py-2">
                <CardContent className="flex gap-6 items-center justify-center p-0">
                    {navItems.map(({ name, href }) => (
                    <Link
                        key={name}
                        href={href}
                        className={cn(
                        "text-sm font-medium transition-colors hover:text-blue-600",
                        pathname === href ? "text-blue-600 dark:text-blue-400" : "text-gray-700 dark:text-gray-300"
                        )}
                    >
                        {pathname === href && <span className="mr-1">•</span>}
                        {name}
                    </Link>
                    ))}
                </CardContent>

                <BorderBeam
                    duration={6}
                    size={400}
                    className="from-transparent via-red-500 to-transparent"
                />
                <BorderBeam
                    duration={6}
                    delay={3}
                    size={400}
                    borderWidth={2}
                    className="from-transparent via-blue-500 to-transparent"
                />
                </Card>
        </div>
        <div className="navbar-end"> 
            <Button asChild><Link href="../login-in-page">Login</Link></Button>
        </div>
    </div>
  );
}

